export const FOOD_GROUPS = [];
export const FOODS = [];
let group = "";
for (const line of rows.trim().split("\n")) {
  if (!line.includes("|")) { group = line.trim(); FOOD_GROUPS.push(group); continue; }
  const [id, name, k, p, f, c, portion, label] = line.split("|");
  FOODS.push({ id, name, k: +k, p: +p, f: +f, c: +c, portion: +portion, label, group, unit: group.startsWith("Напитки") ? "мл" : "г" });
}

const norm = (s) => String(s).toLocaleLowerCase("ru").replace(/ё/g, "е");
/** Поиск по встроенной базе и своим продуктам: совпадение с начала слова выше. */
export function searchFoods(query, custom = []) {
  const q = norm(query).trim();
  const all = [...custom.map((f) => ({ ...f, group: "Мои продукты", unit: f.unit || "г", label: f.label || "порция" })), ...FOODS];
  if (!q) return [];
  return all
    .map((f) => {
      const name = norm(f.name), i = name.indexOf(q);
      if (i < 0) return null;
      return { f, score: (i === 0 ? 0 : name[i - 1] === " " ? 1 : 2) + name.length / 100 };
    })
    .filter(Boolean)
    .sort((a, b) => a.score - b.score)
    .slice(0, 12)
    .map((x) => x.f);
}
export const findFood = (id, custom = []) => custom.find((f) => f.id === id) || FOODS.find((f) => f.id === id);
